数码管显示
#define DUANXUAN P3
sbit WEI1 = P2^6;
sbit WEI2 = P2^7;
int nums[10] = {0x3F, 0x06, 0x5B, 0x4F, 0x66, 0x6D, 0x7D, 0x07, 0x7F, 0x6F};
void delay_ms(unsigned int n)//延时1ms函数
{
	unsigned char i;
    while(n--)
        for(i = 0; i &lt; 113; i++);
}
void display_num(int num)
{
	WEI1 = 0; 
	DUANXUAN = nums[num / 10]; //显示个位
	delay_ms(25);
	WEI1 = 1; 
	WEI2 = 0;  
	DUANXUAN = nums[num % 10]; //显示十位
	delay_ms(25);
	WEI2 = 1; 
}
